#include <stdio.h>

int main(void) {
    int marks[5] = {72, 85, 90, 64, 88};
    int *p = marks;                       /* the array name decays to &marks[0] */
    printf("marks[2] = %d, *(p + 2) = %d, p[2] = %d\n", marks[2], *(p + 2), p[2]);
    printf("p + 1 is %td bytes after p\n", (char *)(p + 1) - (char *)p);
    printf("sizeof marks = %zu bytes, %zu elements\n", sizeof marks, sizeof marks / sizeof marks[0]);
    return 0;
}

#include <stdio.h>

static double average(const int *a, size_t n) {   /* a is just a pointer here */
    long sum = 0;
    for (const int *q = a; q < a + n; q++) sum += *q;
    return (double)sum / (double)n;
}

static size_t looks_like_length(const int *a) {
    return sizeof a / sizeof a[0];                 /* size of a POINTER divided by size of an int */
}

int main(void) {
    int marks[5] = {72, 85, 90, 64, 88};
    size_t n = sizeof marks / sizeof marks[0];     /* correct: computed where the array is declared */
    printf("average = %.1f\n", average(marks, n));
    printf("wrong length inside a function = %zu\n", looks_like_length(marks));
    return 0;
}

