#include <stdio.h>

static void reverse(int *a, int n) {
    int *left = a, *right = a + n - 1;
    while (left < right) {
        int t = *left;
        *left++ = *right;
        *right-- = t;
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int a[1000];
    for (int i = 0; i < n; i++)
        if (scanf("%d", &a[i]) != 1) return 0;
    reverse(a, n);
    for (int i = 0; i < n; i++) printf("%d%c", a[i], i + 1 < n ? ' ' : '\n');
    return 0;
}
